import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.net.URLEncoder
import java.security.MessageDigest
import java.text.SimpleDateFormat
import java.util.Date
import java.util.TreeMap
import java.util.Map
import java.util.TimeZone


String prepareCanonicalRequest(String httpMethodName, String canonicalURI, TreeMap<String, String> queryParameters, TreeMap<String, String> awsHeaders, String payload) {
    StringBuilder canonicalURL = new StringBuilder("")

    canonicalURL.append(httpMethodName).append("\n")

    canonicalURI = canonicalURI == null || canonicalURI.trim().isEmpty() ? "/" : canonicalURI
    canonicalURL.append(canonicalURI).append("\n")

    StringBuilder queryString = new StringBuilder("")
    if (queryParameters != null && !queryParameters.isEmpty()) {
        for (Map.Entry<String, String> entrySet : queryParameters.entrySet()) {
            String key = entrySet.getKey()
            String value = entrySet.getValue()
            queryString.append(key).append("=").append(encodeParameter(value)).append("&")
        }

        queryString.deleteCharAt(queryString.lastIndexOf("&"))

        queryString.append("\n")
    } else {
        queryString.append("\n")
    }
    canonicalURL.append(queryString)

    StringBuilder signedHeaders = new StringBuilder("")
    if (awsHeaders != null && !awsHeaders.isEmpty()) {
        for (Map.Entry<String, String> entrySet : awsHeaders.entrySet()) {
            String key = entrySet.getKey()
            String value = entrySet.getValue()
            signedHeaders.append(key).append(";")
            canonicalURL.append(key).append(":").append(value).append("\n")
        }

        canonicalURL.append("\n")
    } else {
        canonicalURL.append("\n")
    }

    String strSignedHeader = signedHeaders.substring(0, signedHeaders.length() - 1)
    canonicalURL.append(strSignedHeader).append("\n")

    payload = payload == null ? "" : payload
    canonicalURL.append(generateHex(payload))

    return canonicalURL.toString()
}

String prepareStringToSign(String canonicalURL, String amzDate, String currentDate, String regionName, String serviceName) {
    def stringToSign = HMACAlgorithm + "\n"

    stringToSign += amzDate + "\n"

    stringToSign += currentDate + "/" + regionName + "/" + serviceName + "/" + aws4Request + "\n"

    stringToSign += generateHex(canonicalURL)

    return stringToSign
}

String calculateSignature(String stringToSign, String currentDate, String regionName, String serviceName, String secretAccessKey) {

    byte[] signatureKey = getSignatureKey(secretAccessKey, currentDate, regionName, serviceName)

    byte[] signature = HmacSHA256(signatureKey, stringToSign)

    String strHexSignature = bytesToHex(signature)
    return strHexSignature
}

TreeMap<String, String> getHeaders(String accessKeyID, String secretAccessKey, String httpMethodName, String region, String service, String canonicalURI, TreeMap<String, String> queryParameters, TreeMap<String, String> awsHeaders, String payload) {
    String amzDate = getTimeStamp()
    String currentDate = getDate()
    awsHeaders.put("x-amz-date", amzDate);

    String canonicalURL = prepareCanonicalRequest(httpMethodName, canonicalURI, queryParameters, awsHeaders, payload)

    String stringToSign = prepareStringToSign(canonicalURL, amzDate, currentDate, region, service)

    String signature = calculateSignature(stringToSign, currentDate, region, service, secretAccessKey)

    if (signature != null) {
        awsHeaders.put("Authorization", buildAuthorizationString(signature, accessKeyID, currentDate, region, service, awsHeaders))

        return awsHeaders
    } else {
        return null
    }
}

String buildAuthorizationString(String strSignature, String accessKeyID, String currentDate, String regionName, String serviceName, TreeMap<String, String> awsHeaders) {
    StringBuilder signedHeaders = new StringBuilder("")
    if (awsHeaders != null && !awsHeaders.isEmpty()) {
        for (Map.Entry<String, String> entrySet : awsHeaders.entrySet()) {
            String key = entrySet.getKey()
            String value = entrySet.getValue()
            signedHeaders.append(key).append(";")
        }
    }
    String strSignedHeader = signedHeaders.substring(0, signedHeaders.length() - 1)

    StringBuilder authorizationString = new StringBuilder("")
    authorizationString.append(HMACAlgorithm)
    authorizationString.append(" ")
    authorizationString.append("Credential=${accessKeyID}/${currentDate}/${regionName}/${serviceName}/${aws4Request},")
    authorizationString.append("SignedHeaders=${strSignedHeader},")
    authorizationString.append("Signature=${strSignature}")
    return authorizationString.toString()
}

String generateHex(String data) {
    MessageDigest messageDigest

    messageDigest = MessageDigest.getInstance("SHA-256")
    messageDigest.update(data.getBytes("UTF-8"))
    byte[] digest = messageDigest.digest()
    return String.format("%064x", new java.math.BigInteger(1, digest))
}

byte[] HmacSHA256(byte[] key, String data) throws Exception {
    String algorithm = "HmacSHA256"
    Mac mac = Mac.getInstance(algorithm)
    mac.init(new SecretKeySpec(key, algorithm))
    return mac.doFinal(data.getBytes("UTF8"))
}

byte[] getSignatureKey(String key, String date, String regionName, String serviceName) throws Exception {
    byte[] kSecret = ("AWS4" + (key as java.lang.CharSequence)).getBytes("UTF8")
    byte[] kDate = HmacSHA256(kSecret, date)
    byte[] kRegion = HmacSHA256(kDate, regionName)
    byte[] kService = HmacSHA256(kRegion, serviceName)
    byte[] kSigning = HmacSHA256(kService, aws4Request)
    return kSigning
}

static String bytesToHex(byte[] bytes) {
    char[] hexArray = "0123456789ABCDEF".toCharArray()

    char[] hexChars = new char[bytes.length * 2]
    for (int j = 0; j < bytes.length; j++) {
        int v = bytes[j] & 0xFF
        hexChars[j * 2] = hexArray[v >>> 4]
        hexChars[j * 2 + 1] = hexArray[v & 0x0F]
    }
    return new String(hexChars).toLowerCase()
}

String getTimeStamp() {
    SimpleDateFormat dateFormat = new SimpleDateFormat("yyyyMMdd'T'HHmmss'Z'")
    dateFormat.setTimeZone(TimeZone.getTimeZone("UTC"))
    return dateFormat.format(new Date())
}

String getDate() {
    SimpleDateFormat dateFormat = new SimpleDateFormat("yyyyMMdd")
    dateFormat.setTimeZone(TimeZone.getTimeZone("UTC"))
    return dateFormat.format(new Date())
}

String encodeParameter(String param) {
    try {
        return URLEncoder.encode(param, "UTF-8")
    } catch (Exception ignored) {
        return URLEncoder.encode(param)
    }
}

HMACAlgorithm = "AWS4-HMAC-SHA256";
aws4Request = "aws4_request";


String region = "" ?: request.getHeader("AmazonAWSRegion");
String target = "" ?: request.getHeader("AmazonAWSTarget");
String accessKeyID = "" ?: request.getHeader("AmazonAWSAccessKeyID");
String secretAccessKey = "" ?: request.getHeader("AmazonAWSSecretAccessKey");
String payload = request.getBody(java.lang.String.class)


String httpMethod = "POST"
String serviceName = "ce"
String canonicalURI = "/"
String contentType = "application/x-amz-json-1.1"

GString host = "${serviceName}.${region}.amazonaws.com"

TreeMap<String, String> queryParameters = new TreeMap<String, String>()

TreeMap<String, String> awsHeaders = new TreeMap<String, String>()
awsHeaders.put("host", host);
awsHeaders.put("x-amz-target", target);
awsHeaders.put("content-type", contentType);

TreeMap<String, String> headers = getHeaders(accessKeyID, secretAccessKey, httpMethod, region, serviceName, canonicalURI, queryParameters, awsHeaders, payload)


GString endpoint = "https://$host"
for (Map.Entry<String, String> entrySet : headers.entrySet()) {
    request.setHeader(entrySet.getKey(), entrySet.getValue())
}
request.setHeader("dynamoDBEndpoint", endpoint)

result = payload
